    sku: line.sku,
    name: product.name,
    qty: line.qty,
    unitPrice: product.unitPrice,
    vatRate: product.vatRate,
  });
}

// Build invoice
const invoice = {
  customerId,
  issueDate,
  status: 'draft',
  lines: processedLines,
};

