  const discount = (total * (line.discountPercent ?? 0)) / 100;
  return roundCents(discount);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, total: number }} amounts in cents
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  let discount = 0;
  for (const line of invoice.lines) {
    subtotal += lineTotal(line);
    discount += lineDiscount(line);
  }
  const total = Math.max(0, subtotal - discount);
  return {
    subtotal,
    discount,
    total,
  };
}

/**
 * Add or increase a line on a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string, qty: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} input
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check status
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Validate quantity
  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  // Validate discount percent
  const discountError = validateDiscountPercent(discountPercent);
  if (discountError) return fail(discountError);

  // Validate SKU and get product
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  // Create new invoice with updated lines
  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex >= 0) {
    // Line exists, increase qty
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    // New line, add it
    const product = productResult.value;
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: discountPercent ?? 0,
    });
  }

  // Return new invoice
  const newInvoice = {
    ...invoice,
    lines: newLines,
  };
  return ok(newInvoice);
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check status
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Find the line
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) {
    return fail('LINE_NOT_FOUND');
  }

  // Check if this is the last line
  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  // Create new invoice without this line
  const newLines = invoice.lines.filter((line) => line.sku !== sku);
  const newInvoice = {
    ...invoice,
    lines: newLines,
  };
  return ok(newInvoice);
}

/**
 * Issue a draft invoice.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {Array<string>} existingNumbers array of invoice numbers already used
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check status
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Generate invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  // Return new invoice with number and issued status
  const newInvoice = {
    ...invoice,
    number,
    status: 'issued',
  };
  return ok(newInvoice);
}

/**
 * Validate issue date format and that it's a real date.
 * @param {string} dateStr
 * @returns {string | null} error code or null if valid
 */
function validateIssueDate(dateStr) {
  if (typeof dateStr !== 'string') return 'DATE_INVALID';

  // Check format YYYY-MM-DD
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateStr);
  if (!match) return 'DATE_INVALID';

  const year = parseInt(match[1], 10);
  const month = parseInt(match[2], 10);
  const day = parseInt(match[3], 10);

  // Validate month and day ranges
  if (month < 1 || month > 12 || day < 1 || day > 31) {
    return 'DATE_INVALID';
  }

  // Check if it's a real date by creating a Date and verifying
  const date = new Date(`${dateStr}T00:00:00Z`);
  if (isNaN(date.getTime())) return 'DATE_INVALID';

  // Verify that the date components match (handles invalid dates like Feb 30)
  if (date.getUTCFullYear() !== year || date.getUTCMonth() + 1 !== month || date.getUTCDate() !== day) {
    return 'DATE_INVALID';
  }

  return null;
}

