    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },    // 42500 - 4250 = 38250
      { sku: 'DEV-HOUR', qty: 3, discountPercent: 20 },    // 28500 - 5700 = 22800
      { sku: 'COPY-HOUR', qty: 2 },                        // 12000 - 0 = 12000
