test('invoiceTotals with multiple lines and varying discounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },    // 42500 - 4250 = 38250
      { sku: 'DEV-HOUR', qty: 3, discountPercent: 20 },    // 28500 - 5700 = 22800
      { sku: 'COPY-HOUR', qty: 2 },                        // 12000 - 0 = 12000
    ],
  });
  const totals = invoiceTotals(result.value);
  // subtotal: 42500 + 28500 + 12000 = 83000
  // discount: 4250 + 5700 + 0 = 9950
  // total: 83000 - 9950 = 73050
  assert.equal(totals.subtotal, 83000);
  assert.equal(totals.discount, 9950);
  assert.equal(totals.total, 73050);
});

test('invoiceTotals clamps total at 0', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 1000, discountPercent: 100 }],
